Lemma wa3_rows0 : forall (k : nat)
    (sp gp tp t2 s9 s10 s11 t6 a0 a1 a6 s6 s7 s8 : word) F fc (m : mem) (dh dwb nfw lwb swpl dwpl PS0 PD0 SR sn DR dn : Z),
  Z.of_nat k = dh -> (1 <= k)%nat -> dh <= 20000 ->
  dwb = 32 * nfw + lwb -> 0 <= nfw -> 0 <= lwb < 32 -> 0 < dwb -> dwb <= 8 * 20000 ->
  0 < swpl <= 2^20 -> 0 < dwpl <= 2^20 ->
  0 < SR -> SR mod 4 = 0 -> SR + sn <= 2^47 -> 0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> PS0 mod 4 = 0 -> PD0 mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  (forall i', 0 <= i' < dh -> SR <= PS0 + 4 * (swpl * i') /\ PS0 + 4 * (swpl * i') + 4 * (nfw + 1) <= SR + sn + 4 * (if lwb =? 0 then 1 else 0)) ->
  (forall i', 0 <= i' < dh -> DR <= PD0 + 4 * (dwpl * i') /\ PD0 + 4 * (dwpl * i') + 4 * (nfw + 1) <= DR + dn + 4 * (if lwb =? 0 then 1 else 0)) ->
  wr_at asegs m SR sn -> acc asegs m SR sn -> wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (wa3_rows_exit (Z_to_bv 64 dh) sp gp tp (Z_to_bv 64 lwb) (Z_to_bv 64 PD0) t2 (Z_to_bv 64 (- nfw)) (Z_to_bv 64 (dwpl * 4)) (Z_to_bv 64 PS0)
               (Z_to_bv 64 dwpl) (Z_to_bv 64 2147450880) (Z_to_bv 64 swpl) (Z_to_bv 64 (swpl * 4)) (Z_to_bv 64 32) s9 s10 s11 (Z_to_bv 64 dwb) t6 F fc m DR dn)
    (MS (mkR (Z_to_bv 64 dh) sp gp tp (Z_to_bv 64 lwb) (Z_to_bv 64 PD0) t2 (Z_to_bv 64 (- nfw)) (Z_to_bv 64 (dwpl * 4)) a0 a1 (Z_to_bv 64 PS0) (Z_to_bv 64 0)
